UPDATE /*LGVATT60050.updateAttendance*/
       tb_att_result_n 
SET    TIME_AND_ATTENDANCE_CODE        = #{attendanceCode}             
     , work_hours                      = #{workHours}                 
     , time_attend_detail_code         = #{attendDetailCode}
     , time_attend_input_reason_desc   = #{reasonDesc}
     , last_update_user_id             = NVL(#{USER_SESSION.applicationUserId}, '247970')
     , last_update_date                = trunc(sysdate)
WHERE  employee_no                     = #{employeeNo}     
and time_and_attendance_date           = to_date(#{dayOfMonth},'dd/mm/yyyy')
